CREATE TABLE farm_targets(id TEXT PRIMARY KEY,name TEXT NOT NULL,host TEXT NOT NULL,port INTEGER NOT NULL,transport TEXT NOT NULL,enabled INTEGER NOT NULL,revision INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,author_id TEXT NOT NULL);
CREATE TABLE farm_exploits(id TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,version TEXT NOT NULL,manifest TEXT NOT NULL,target_ids TEXT NOT NULL,interval_seconds INTEGER,next_run INTEGER,initiated_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE farm_versions(exploit_id TEXT NOT NULL,version TEXT NOT NULL,sha256 TEXT NOT NULL,path TEXT NOT NULL,created_at INTEGER NOT NULL,author_id TEXT NOT NULL,PRIMARY KEY(exploit_id,version));
CREATE TABLE farm_runs(id TEXT PRIMARY KEY,exploit_id TEXT NOT NULL,version TEXT NOT NULL,manifest TEXT NOT NULL,target_ids TEXT NOT NULL,initiated_by TEXT NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL,started_at INTEGER,finished_at INTEGER,stdout TEXT NOT NULL DEFAULT '',stderr TEXT NOT NULL DEFAULT '',exit_code INTEGER,idempotency_key TEXT UNIQUE,request_hash TEXT);
CREATE INDEX farm_runs_queue ON farm_runs(status,created_at);
